 stats=[('2012', 'year it was described'), ('Deep', 'non-REM sleep is when it peaks'), ('1', 'team: Nedergaard\'s lab'), ('2', 'waste proteins: beta-amyloid and tau')],
 more=['Waste proteins like beta-amyloid and tau are linked to diseases such as Alzheimer\'s.', 'The study of zolpidem was done in mice.', 'Brain waves, blood flow and fluid movement work together.'],
 gloss=[('Glymphatic system', 'The brain\'s waste-clearing network.'), ('Cerebrospinal fluid', 'The clear fluid that surrounds the brain.')],
 tryit='Tonight, go to bed at a regular time and let your brain do its cleaning. Notice how you feel in the morning!',
